/**
 * The arclaw logo as data. Everything that draws it builds from here: components/Logo.tsx, lib/og (share cards),
 * app/icon.svg and brand/render.mjs (brand/logo/*.svg). Only erasable TypeScript, so Node can import it directly.
 *
 * Mark: a claw seen front on, on a 24 unit grid. A cable and a hub in cream, three prongs in the claw accent.
 * Wordmark: "arclaw" traced from Geist Medium (lib/brand/wordmark.ts, generated by brand/wordmark.mjs).
 */
import { WORD_BASELINE, WORD_H, WORD_PATH, WORD_W } from "./wordmark.ts";

export const INK = "#0C0C0E";
export const CREAM = "#ECE6DA";
export const CLAW = "#FF5A1F";

export const MARK_SIZE = 24;
/** Prong stroke width in mark units. */
export const PRONG_W = 2.2;

/** Cable and hub: filled. */
export const MARK_BODY = "M11 1h2v5h-2z M7.5 6h9a1 1 0 0 1 1 1v2.5a1 1 0 0 1-1 1h-9a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1z";
/** The three prongs: stroked, butt caps, mitre joins. */
export const MARK_PRONGS = "M9 10.5L4.6 15V18.6L8.2 22M15 10.5L19.4 15V18.6L15.8 22M12 10.5V20";

export { WORD_BASELINE, WORD_H, WORD_PATH, WORD_W };

/** Lockup layout: mark left at 40 units, name right at 0.8 of that, baseline on the prong tips. */
const LOCK_MARK = 40;
const LOCK_GAP = 12;
export const WORD_SCALE = (LOCK_MARK * 0.8) / WORD_H;
const LOCK_BASE = (22 / MARK_SIZE) * LOCK_MARK;
const LOCK_WORD_Y = LOCK_BASE - WORD_BASELINE * WORD_SCALE;
export const LOCKUP_W = Math.ceil(LOCK_MARK + LOCK_GAP + WORD_W * WORD_SCALE);
export const LOCKUP_H = LOCK_MARK;

type Colors = { body: string; prongs: string; word: string };
const FULL: Colors = { body: CREAM, prongs: CLAW, word: CREAM };
const ON_LIGHT: Colors = { body: INK, prongs: CLAW, word: INK };
const MONO: Colors = { body: "currentColor", prongs: "currentColor", word: "currentColor" };

export type LogoTone = "dark" | "light" | "mono";
const TONES: Record<LogoTone, Colors> = { dark: FULL, light: ON_LIGHT, mono: MONO };

/** Inner SVG of the mark in its own 24 unit box. */
export function markInner(tone: LogoTone = "dark"): string {
  const c = TONES[tone];
  return `<path fill="${c.body}" d="${MARK_BODY}"/><path fill="none" stroke="${c.prongs}" stroke-width="${PRONG_W}" stroke-linecap="butt" stroke-linejoin="miter" d="${MARK_PRONGS}"/>`;
}

const svg = (w: number, h: number, body: string, label = "arclaw") =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-label="${label}">${body}</svg>`;

export const logoSvg = {
  mark: (tone: LogoTone = "dark") => svg(MARK_SIZE, MARK_SIZE, markInner(tone)),
  wordmark: (tone: LogoTone = "dark") => svg(Math.ceil(WORD_W), Math.ceil(WORD_H), `<path fill="${TONES[tone].word}" d="${WORD_PATH}"/>`),
  lockup: (tone: LogoTone = "dark") => {
    const s = LOCK_MARK / MARK_SIZE;
    return svg(
      LOCKUP_W,
      LOCKUP_H,
      `<g transform="scale(${s})">${markInner(tone)}</g><path fill="${TONES[tone].word}" transform="translate(${LOCK_MARK + LOCK_GAP} ${LOCK_WORD_Y.toFixed(2)}) scale(${WORD_SCALE.toFixed(4)})" d="${WORD_PATH}"/>`,
    );
  },
  /** App icon: the mark on an ink square, radius 18% (DESIGN.md radius 18 at 100). */
  tile: (size = 512) => {
    const pad = size * 0.2;
    const s = (size - pad * 2) / MARK_SIZE;
    return svg(size, size, `<rect width="${size}" height="${size}" rx="${size * 0.18}" fill="${INK}"/><g transform="translate(${pad} ${pad}) scale(${s})">${markInner("dark")}</g>`);
  },
};

/** Numbers React needs to place the lockup's parts. */
export const LOCKUP = { mark: LOCK_MARK, gap: LOCK_GAP, wordY: LOCK_WORD_Y, wordScale: WORD_SCALE } as const;
